typedef struct { char *d,*repo,*src; DarcCatalog cat; } VFix;

static TestProc vr_init(const char*r){const char*a[]={"./darc","init",r,NULL};return test_exec(a,NULL);}
static TestProc vr_snap(const char*r,const char*s,long long ts){char tb[32];snprintf(tb,sizeof tb,"%lld",ts);const char*a[]={"./darc","--repo",r,"snapshot","create",s,"--timestamp",tb,NULL};return test_exec(a,NULL);}
static TestProc vr_verify(const char*r,const char*level,bool repair,const char*fmt){const char*a[14];int n=0;a[n++]="./darc";a[n++]="--repo";a[n++]=r;a[n++]="verify";a[n++]="--level";a[n++]=level;if(repair)a[n++]="--repair";if(fmt){a[n++]="--format";a[n++]=fmt;}a[n]=NULL;return test_exec(a,NULL);}
static TestProc vr_gc(const char*r,bool dry){const char*a[8];int n=0;a[n++]="./darc";a[n++]="--repo";a[n++]=r;a[n++]="gc";if(dry)a[n++]="--dry-run";a[n]=NULL;return test_exec(a,NULL);}
static TestProc vr_del(const char*r,const char*sel){const char*a[]={"./darc","--repo",r,"snapshot","delete",sel,"--yes",NULL};return test_exec(a,NULL);}
static void fill_bytes(uint8_t*b,size_t n,uint32_t seed){uint32_t x=seed?seed:1;for(size_t i=0;i<n;i++){x^=x<<13;x^=x>>17;x^=x<<5;b[i]=(uint8_t)(x>>24);}}
static bool write_random_file(const char*p,size_t n,uint32_t seed){int fd=open(p,O_CREAT|O_TRUNC|O_WRONLY|O_CLOEXEC,0644);if(fd<0)return false;uint8_t b[4096];size_t off=0;while(off<n){size_t z=n-off<sizeof b?n-off:sizeof b;fill_bytes(b,z,seed+(uint32_t)(off/sizeof b)*977u);if(darc_write_all(fd,b,z)){close(fd);return false;}off+=z;}return close(fd)==0;}
static bool vfix_make(VFix*f,const char*name){memset(f,0,sizeof* f);f->d=test_case_dir(name);if(!f->d)return false;f->repo=test_path(f->d,"repo");f->src=test_path(f->d,"src");if(!f->repo||!f->src||test_mkdir(f->src))return false;for(int i=0;i<8;i++){char nm[32];snprintf(nm,sizeof nm,"f%d.bin",i);char*p=test_path(f->src,nm);bool ok=p&&write_random_file(p,4096,(uint32_t)(0x1234+i*97));free(p);if(!ok)return false;}TestProc x=vr_init(f->repo);bool ok=x.code==0;test_proc_free(&x);if(!ok)return false;x=vr_snap(f->repo,f->src,1000);ok=x.code==0;test_proc_free(&x);if(!ok)return false;if(darc_catalog_load(f->repo,&f->cat)||f->cat.n<1||f->cat.v[0].n<2)return false;return true;}
static void vfix_free(VFix*f){darc_catalog_free(&f->cat);free(f->src);free(f->repo);free(f->d);memset(f,0,sizeof* f);}
static bool obj_read(const char*r,const DarcCid*c,DarcBuf*b){char*p=darc_object_path(r,c);bool ok=p&&!test_read(p,b);free(p);return ok;}
static bool obj_unlink(const char*r,const DarcCid*c){char*p=darc_object_path(r,c);bool ok=p&&unlink(p)==0;free(p);return ok;}
static bool obj_flip_at(const char*r,const DarcCid*c,off_t off){char*p=darc_object_path(r,c);if(!p)return false;int fd=open(p,O_RDWR|O_CLOEXEC);uint8_t b=0;bool ok=fd>=0&&pread(fd,&b,1,off)==1;if(ok){b^=0x5a;ok=pwrite(fd,&b,1,off)==1&&fsync(fd)==0;}if(fd>=0)close(fd);free(p);return ok;}
static bool obj_flip_payload(const char*r,const DarcCid*c){return obj_flip_at(r,c,32);}
static bool obj_flip_crc(const char*r,const DarcCid*c){char*p=darc_object_path(r,c);if(!p)return false;struct stat st;bool ok=!stat(p,&st)&&st.st_size>36;free(p);return ok&&obj_flip_at(r,c,st.st_size-1);}
static bool obj_truncate(const char*r,const DarcCid*c){char*p=darc_object_path(r,c);if(!p)return false;struct stat st;bool ok=!stat(p,&st)&&st.st_size>40&&truncate(p,st.st_size-7)==0;free(p);return ok;}
static bool cid_loads(const char*r,const DarcCid*c){DarcObject o;int rc=darc_object_load(r,c,&o,1);if(!rc)darc_object_free(&o);return rc==0;}
static bool json_ok(const char*s){if(!s)return false;char e[256];size_t l=0,c=0;DarcValue*v=darc_json_parse((const uint8_t*)s,strlen(s),e,sizeof e,&l,&c);if(!v)return false;darc_value_free(v);return true;}
static bool get_head_flat(const char*r,DarcCid*sid,DarcSnapshotObj*s,DarcFlatTree*t){memset(s,0,sizeof* s);memset(t,0,sizeof* t);if(darc_resolve_snapshot(r,"HEAD",sid,s))return false;if(darc_flatten_snapshot(r,s,t)){darc_snapshot_free(s);return false;}return true;}
static size_t ref_count(const char*r){char*p=test_path(r,"refs/snapshots");DIR*d=p?opendir(p):NULL;size_t n=0;if(d){struct dirent*e;while((e=readdir(d)))if(e->d_name[0]!='.')n++;closedir(d);}free(p);return n;}
static bool add_orphan(const char*r,DarcCid*out,size_t n){uint8_t*b=malloc(n?n:1);if(!b)return false;fill_bytes(b,n,0xa5a55a5a);DarcConfig c;darc_config_defaults(&c);c.compression_enabled=false;bool nn=false;uint64_t sb=0;int rc=darc_object_store(r,OBJ_CHUNK,b,n,&c,out,&sb,&nn);darc_config_free(&c);free(b);return rc==0&&nn;}
static bool index_sorted(const char*r){char*p=test_path(r,"index/chunks.idx");DarcBuf b={0};bool ok=p&&!test_read(p,&b);free(p);if(!ok||b.len<24||memcmp(b.data,"DARCIDX1",8)){darc_buf_free(&b);return false;}uint64_t n=darc_rd_u64(b.data+12);if(n>SIZE_MAX/52||20+(size_t)n*52+4!=b.len){darc_buf_free(&b);return false;}size_t o=20;for(uint64_t i=1;i<n;i++){o+=52;if(memcmp(b.data+o-52,b.data+o,32)>=0){darc_buf_free(&b);return false;}}darc_buf_free(&b);return true;}
static bool parse_u64_after(const char*s,const char*key,uint64_t*out){const char*p=strstr(s,key);if(!p)return false;p+=strlen(key);while(*p==' '||*p==':')p++;char*e=NULL;errno=0;unsigned long long v=strtoull(p,&e,10);if(errno||e==p)return false;*out=(uint64_t)v;return true;}

/* Independent recursive digest for dry-run mutation checks. */
static int namecmp(const void*a,const void*b){return strcmp(*(char*const*)a,*(char*const*)b);}
static bool digest_tree_rec(const char*root,const char*rel,DarcSha256*sh){char*dir=rel&&*rel?test_path(root,rel):strdup(root);if(!dir)return false;DIR*d=opendir(dir);if(!d){free(dir);return false;}char**names=NULL;size_t n=0;struct dirent*e;while((e=readdir(d)))if(strcmp(e->d_name,".")&&strcmp(e->d_name,"..")){char**v=realloc(names,(n+1)*sizeof*names);if(!v){closedir(d);free(dir);return false;}names=v;names[n++]=strdup(e->d_name);}closedir(d);if(n>1)qsort(names,n,sizeof*names,namecmp);bool ok=true;for(size_t i=0;i<n&&ok;i++){char*nr=rel&&*rel?test_path(rel,names[i]):strdup(names[i]);char*p=test_path(root,nr);struct stat st;if(!nr||!p||lstat(p,&st)){free(nr);free(p);ok=false;break;}uint64_t rl=(uint64_t)strlen(nr);darc_sha256_update(sh,&rl,sizeof rl);darc_sha256_update(sh,nr,(size_t)rl);uint32_t m=(uint32_t)(st.st_mode&S_IFMT);darc_sha256_update(sh,&m,sizeof m);if(S_ISREG(st.st_mode)){DarcBuf b={0};if(test_read(p,&b))ok=false;else{uint64_t z=(uint64_t)b.len;darc_sha256_update(sh,&z,sizeof z);darc_sha256_update(sh,b.data,b.len);darc_buf_free(&b);}}else if(S_ISDIR(st.st_mode))ok=digest_tree_rec(root,nr,sh);free(nr);free(p);}for(size_t i=0;i<n;i++)free(names[i]);free(names);free(dir);return ok;}
static bool repo_digest(const char*r,uint8_t out[32]){DarcSha256 sh;darc_sha256_init(&sh);if(!digest_tree_rec(r,"",&sh))return false;darc_sha256_final(&sh,out);return true;}

